let settings, records, recipientState, failNext, seq, timer;
let templateStore, templateDraft, activeTemplate='outreach';
let mailing;
let outreachState;
const esc = (s) => String(s).replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize = (s) => s.trim().toLowerCase();
function addMonths(start,n){if(!n)return '';const [y,m,d]=start.split('-').map(Number);const target=new Date(Date.UTC(y,m-1+n,1));const max=new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate();target.setUTCDate(Math.min(d,max));return target.toISOString().slice(0,10);}
function record(type,email,start,end,reason){return {id:++seq,type,email,start,end,reason,ended:false,history:[`${today} · ${type==='manual'?'管理员添加':sources[type]} · ${reason}`]};}
function statusAt(r,at){return r.ended&&r.ended<=at?'ended':r.end&&r.end<=at?'expired':r.start>at?'future':'active';}
function reset(clearSaved=false){if(clearSaved)localStorage.removeItem('unsubscribe-prototype-v6');resetOutreach();mailing={serviceUrl:'https://mail.example.test/unsubscribe',serviceSaved:true,previewChecked:false,recordReviewed:false,sender:'hello@example.test',entry:'campaign',routeSaved:false,templateSaved:false,firstBatch:false,receipt:null,lastBatch:null,serviceChecked:false,walking:false,step:0,completed:[]};settings={...defaults};templateStore={outreach:newTemplate('产品调研邮件'),quick:newTemplate('调研邀请快捷模板')};activeTemplate='outreach';templateDraft={...templateStore.outreach};seq=0;records=[record('manual','mia@example.test',today,'2027-05-05','应客户请求，暂停群发半年'),record('hard','bounced@example.test','2026-11-04','','供应商确认永久退信'),record('manual','sam@example.test','2026-05-03','2026-11-03','历史员工代为退订')];recipientState='idle';failNext=false;$('settingsForm').reset();$('sendForm').reset();$('batchResult').innerHTML='';$('serviceResult').innerHTML='';$('nativeVisible').checked=false;$('native').hidden=true;$('search').value='';$('filter').value='all';$('status').value='all';$('result').innerHTML='<span class="label">模拟结果</span><h2>等待检查</h2><p>可以先在「收件人体验」确认退订，再检查同一地址。</p>';renderMail();renderList();renderTemplate();if(typeof renderBindingSettings==='function'){renderBindingSettings();renderCompose();renderGuide();}}
function show(tab,update=true){const contactRoute=({settings:'unsubscribes',list:'unsubscribes',unsubscribes:'unsubscribes',blacklist:'blacklist',contacts:'contacts'})[tab];if(contactRoute)tab='contacts';if(tab==='template'&&activeTemplate==='outreach'){if(!outreachState.draft){openOutreachEditor(outreachState.currentId,3);return;}outreachState.step=3;tab='outreachEditor';}if(!document.querySelector(`.view#${CSS.escape(tab||'list')}`))tab='list';tab=tab||'list';document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==tab);document.querySelectorAll('[data-tab]').forEach(b=>b.dataset.tab===tab?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current'));document.body.classList.toggle('templatepage',['template','outreachEditor'].includes(tab));document.body.classList.toggle('composepage',tab==='compose');document.querySelector('.top b').textContent=tab==='template'?(activeTemplate==='quick'?'消息模板库':'主动触达'):'设置';document.querySelectorAll('.appnav>span').forEach((n,i)=>n.classList.toggle('selected',i===(tab==='template'?3:4)));document.body.classList.toggle('public',tab==='recipient');document.body.classList.toggle('reviewpage',['flow','scope','send','email'].includes(tab));if(update&&location.hash!==`#${tab}`)history.replaceState(null,'',`#${tab}`);if(tab==='list')renderList();if(typeof renderBindingSettings==='function'){if(tab==='settings')renderBindingSettings();if(tab==='compose')renderCompose();if(tab==='flow')renderFlowMap();if(tab==='email')renderBoundMail();}if(tab==='recipient'&&recipientState==='idle'){recipientState=selfActive()?'already':'confirm';renderRecipient();}syncOutreachView(tab);syncContactsView(contactRoute);window.scrollTo(0,0);}
function toast(msg){clearTimeout(timer);$('toast').textContent=msg;$('toast').hidden=false;timer=setTimeout(()=>$('toast').hidden=true,3100);}
function openModal(title,body){$('modalBody').innerHTML=`<div class="modalHead"><h2 id="modalTitle">${esc(title)}</h2><button data-close type="button" aria-label="关闭">✕</button></div>${body}`;if(!$('modal').open)$('modal').showModal();}
function note(i){const [title,...blocks]=notes[i];const num=x=>String(x+1).padStart(2,'0');openModal(`${num(i)} ${title}`,`<nav class="noteNav" aria-label="批注目录">${notes.map((_,j)=>`<button data-note="${j}" aria-pressed="${i===j}">${num(j)}</button>`).join('')}</nav><div class="noteBody">${blocks.map(b=>`<p>${esc(b)}</p>`).join('')}</div>`);}
function renderMail(){renderTemplateUsage();const t=templateStore[activeTemplate];$('sentSubject').textContent=t.subject;$('sentBody').textContent=t.body;$('fallbackHint').textContent=t.enabled?'':'此示例模板未启用退订，请回模板添加。';$('footLink').className=t.enabled&&t.appearance==='button'?'unsubButton':'text';$('mailBrand').textContent='发件人';$('footLink').textContent=t.enabled?t.label:settings.footer;renderRecipient();if(typeof renderBoundMail==='function')renderBoundMail();}
function selfActive(){return records.some(r=>r.type==='self'&&r.email===demoMail&&statusAt(r,today)==='active');}
function renderRecipient(){const scope=`<p>将停止向 <strong>a•••@example.test</strong> 发送后续群发邮件。正常工单回复不受影响。</p>`;const content={idle:`<h2>打开邮件中的退订入口</h2><p>点击左边邮件正文末尾的链接，或使用邮箱顶部的「取消订阅」。</p>`,confirm:`<h2>退订后续群发邮件？</h2>${scope}<div class="actions"><button class="primary" id="confirmUnsub">确认退订</button><button id="cancelUnsub">返回邮件</button></div>`,success:`<span class="pill good">已保存</span><h2>退订成功</h2>${scope}<small>退订持续有效，直到你重新同意订阅。你可以关闭此页。</small>`,native:`<span class="pill good">邮箱已收到结果</span><h2>已取消订阅</h2>${scope}<small>这是邮箱原生一键退订的模拟反馈，实际展示由邮箱客户端决定。</small>`,already:`<h2>你已退订此类邮件</h2>${scope}`,invalid:`<h2>此退订链接不可用</h2><p>本次没有更改你的订阅。请尝试发件方较新的邮件链接，或联系发件方处理。</p><button id="cancelUnsub">返回邮件</button>`,failed:`<h2>暂时无法保存退订</h2><p>本次没有更改你的订阅，请重试。</p><button class="primary" id="confirmUnsub">重试退订</button>`};$('recipientPage').innerHTML=`<span class="label">02　退订反馈</span>${content[recipientState]}`;}
function unsubscribe(via){if(!mailing.receipt){toast('请先模拟发送邮件，再体验退订。');return;}if(failNext){failNext=false;recipientState='failed';renderRecipient();return;}if(selfActive()){recipientState='already';renderRecipient();return;}const r=record('self',demoMail,today,'',via==='native'?'邮箱一键退订':'邮件正文确认');if(mailing?.receipt){r.sender=mailing.receipt.sender;r.entry=mailing.receipt.entry;r.template=mailing.receipt.templateName;r.history.push('来源模板：'+r.template+' · 来源邮件：'+r.sender+' · '+(r.entry==='campaign'?'主动触达计划':'新建工单导入'));}records.unshift(r);recipientState=via==='native'?'native':'success';renderRecipient();renderList();if(typeof renderGuide==='function')renderGuide();}
function renderList(){const q=normalize($('search').value),f=$('filter').value,s=$('status').value;$('stats').innerHTML=[['self','客户退订'],['manual','员工代为退订'],['hard','硬禁发']].map(([k,t])=>`<div><small>${t} · 生效中</small><b>${records.filter(r=>r.type===k&&statusAt(r,today)==='active').length}</b></div>`).join('');const shown=records.filter(r=>r.email.includes(q)&&(f==='all'||r.type===f)&&(s==='all'||statusAt(r,today)===s));$('records').innerHTML=shown.length?shown.map(r=>{const s=statusAt(r,today);return `<tr><td><b>${esc(r.email)}</b></td><td>${sources[r.type]}</td><td>${r.type==='hard'?'所有适用邮件':'后续群发'}</td><td>${r.start}<small>${r.end?`到期：${r.end}`:'持续有效'}</small></td><td><span class="pill ${s==='active'?'wait':''}">${stateText[s]}</span></td><td><button data-detail="${r.id}">详情</button>${r.type==='manual'&&s==='active'?`<button data-edit="${r.id}">改期</button><button data-end="${r.id}">解除</button>`:''}</td></tr>`;}).join(''):'<tr><td colspan="6" class="empty">没有符合条件的记录</td></tr>';}
function detail(r){if(r.type==='self'){mailing.recordReviewed=true;renderGuide();}openModal('限制详情',`<p><b>${esc(r.email)}</b></p><p>${sources[r.type]} · ${stateText[statusAt(r,today)]} · ${r.type==='hard'?'适用全部邮件':'后续群发'}</p><p>生效 ${r.start} · ${r.end?'到期 '+r.end:'持续有效'}</p><p>原因：${esc(r.reason)}</p><hr><b>操作记录</b><ul>${r.history.map(h=>`<li>${esc(h)}</li>`).join('')}</ul>${r.type!=='manual'?'<small>此记录只读。收件人偏好只能由本人重新授权；硬禁发按独立流程处理。</small>':''}`);}
function limitForm(r){const defaultEnd=addMonths(today,settings.term);openModal(r?'修改员工代为退订期限':'添加员工代为退订',`<form id="limitForm"><div class="field"><label for="limitEmail">收件邮箱</label><input id="limitEmail" type="email" required ${r?'readonly':''} value="${r?esc(r.email):''}" placeholder="name@example.test"></div><div class="field"><b>限制范围</b><span class="pill">后续群发</span></div><div class="field"><label for="limitTerm">期限</label><select id="limitTerm"><option value="1">1 个月</option><option value="3">3 个月</option><option value="6">6 个月</option><option value="12">12 个月</option><option value="0">不限期</option><option value="custom">指定到期日</option></select></div><div class="field" id="dateField"><label for="limitDate">到期日</label><input id="limitDate" type="date" min="2026-11-06" value="${r?r.end:defaultEnd}"><small>到期日 00:00 起不再命中这条限制（租户时区）。</small></div><div class="field"><label for="limitReason">${r?'改期原因':'限制原因'}</label><input id="limitReason" required maxlength="120" placeholder="例如：客户要求暂停半年"></div><p class="error" id="limitError" role="alert" hidden></p><div class="actions"><button class="primary" type="submit">确认保存</button><button type="button" data-close>取消</button></div></form>`);
  $('limitTerm').value=r?(r.end?'custom':'0'):String(settings.term);const update=()=>{const term=$('limitTerm').value;$('dateField').hidden=term==='0';$('limitDate').readOnly=term!=='custom';$('limitDate').required=term!=='0';if(term!=='custom')$('limitDate').value=addMonths(today,Number(term));};update();$('limitTerm').addEventListener('change',update);
  $('limitForm').addEventListener('submit',e=>{e.preventDefault();const email=normalize($('limitEmail').value),end=$('limitTerm').value==='0'?'':$('limitDate').value,reason=$('limitReason').value.trim();const err=m=>{$('limitError').textContent=m;$('limitError').hidden=false;};if(!reason)return err('请填写原因。');if(end&&end<=today)return err('到期日应晚于今天。');if(!r&&records.some(x=>x.type==='manual'&&x.email===email&&statusAt(x,today)==='active'))return err('该邮箱已有生效中的员工代为退订，请查看原记录并改期。');if(r){r.history.push(`${today} · 改期 ${r.end||'不限期'} → ${end||'不限期'} · ${reason}`);r.end=end;}else records.unshift(record('manual',email,today,end,reason));$('modal').close();renderList();toast('员工代为退订已保存');});
}
function endForm(r){openModal('解除这条员工代为退订？',`<p>只解除 <b>${esc(r.email)}</b> 的员工代为退订。若同一邮箱有自助退订或硬禁发，仍按相应规则处理。</p><form id="endForm"><div class="field"><label for="endReason">解除原因</label><input id="endReason" required maxlength="120"></div><p class="error" id="endError" hidden>请填写解除原因。</p><div class="actions"><button class="primary" type="submit">确认解除</button><button type="button" data-close>取消</button></div></form>`);$('endForm').addEventListener('submit',e=>{e.preventDefault();const reason=$('endReason').value.trim();if(!reason){$('endError').hidden=false;return;}r.ended=today;r.history.push(`${today} · 解除 · ${reason}`);$('modal').close();renderList();toast('员工代为退订已解除');});}
function simulate(){const email=normalize($('target').value),date=$('simDate').value,channel=$('channel').value,isBulk=channel!=='reply';const hits=records.filter(r=>r.email===email&&statusAt(r,date)==='active'),hard=hits.filter(r=>r.type==='hard'),opt=hits.filter(r=>r.type!=='hard');const [title,tone,desc]=hard.length?['拦截：硬禁发','bad','按独立硬禁发规则处理。']:isBulk&&opt.length?['跳过：后续群发限制','wait','该收件人不参与本次群发，其他收件人继续逐一检查。']:['通过退订检查','good',isBulk?'未命中退订或人工群发限制；继续原发送检查。':'普通工单回复不受群发退订限制；继续原权限、渠道等检查。'];const matched=hard.length?hard:isBulk?opt:[];$('result').innerHTML=`<span class="label">模拟结果 · ${esc(date)}</span><h2><span class="pill ${tone}">${title}</span></h2><p>${desc}</p><p>按实际入口检查，不要求选择“邮件用途”。</p>${matched.length?'<ul>'+matched.map(r=>'<li>'+sources[r.type]+' · '+(r.end?'到期 '+r.end:'持续有效')+'</li>').join('')+'</ul>':''}<small>本次为新增规则的模拟，未提交邮件服务。</small>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){show(b.dataset.tab);return;}if(b.dataset.note!==undefined){note(Number(b.dataset.note));return;}if(b.hasAttribute('data-close')){$('modal').close();return;}const key=['detail','edit','end'].find(k=>b.dataset[k]);if(key){const r=records.find(x=>x.id===Number(b.dataset[key]));if(r)({detail,edit:limitForm,end:endForm})[key](r);return;}switch(b.id){case 'reset': reset(true);show('list');toast('演示已重置');break;case 'footLink':recipientState=selfActive()?'already':'confirm';renderRecipient();show('recipient');break;case 'native':unsubscribe('native');show('recipient');break;case 'confirmUnsub':unsubscribe('body');break;case 'cancelUnsub':recipientState='idle';renderRecipient();show('email');break;case 'invalid':failNext=false;recipientState='invalid';renderRecipient();break;case 'failed':failNext=true;recipientState=selfActive()?'already':'confirm';if(selfActive())toast('该地址已退订，重置演示后可测试失败分支');else toast('下一次确认将模拟保存失败');renderRecipient();break;case 'newLimit':limitForm();break;}});
$('settingsForm').addEventListener('submit',e=>{e.preventDefault();const footer=$('footer').value.trim();if(!footer){toast('请填写默认退订文案');return;}settings={...settings,footer,term:Number($('term').value)};renderMail();renderList();renderTemplatePreview();renderBindingSettings();renderCompose();renderGuide();toast('默认设置已保存');});
$('sendForm').addEventListener('submit',e=>{e.preventDefault();simulate();});window.addEventListener('hashchange',()=>show(location.hash.slice(1),false));
function newTemplate(name){return {name,subject:'参加产品调研，领取试用机会',body:'你好！我们想邀请你参与一次耳机体验调研。参与者有机会获赠试用产品。',enabled:false,native:true,label:'退订此类邮件',appearance:'link'};}
function readTemplate(){if(activeTemplate==='quick')templateDraft.name=$('templateSubject').value;else templateDraft.subject=$('templateSubject').value;templateDraft.body=$('templateBody').value;}
function renderTemplate(){if(!templateDraft)return;const quick=activeTemplate==='quick';$('templateCrumb').textContent=quick?'消息模板库 / 编辑模板':'主动触达 / 编辑计划 / 消息内容';$('templateTitle').textContent=quick?'编辑消息模板':'产品调研邮件';$('templateSubjectLabel').textContent=quick?'模板名称':'邮件主题';$('insertVariables').hidden=quick;$('formatBar').textContent=quick?'标题 ▾　B　I　U　S　❞　☷　1.　图片　多语言 Original ▾':'Aa　 B　 I　 ☷　 ↗';document.body.classList.toggle('quicktemplate',quick);$('templateSource').value=activeTemplate;$('templateSubject').value=quick?templateDraft.name:templateDraft.subject;$('templateBody').value=templateDraft.body;renderTemplatePreview();mountOutreachTemplate();}
function renderTemplatePreview(){if(!templateDraft)return;$('draftSubject').textContent=templateDraft.subject;$('draftBody').textContent=templateDraft.body;$('draftUnsub').innerHTML=templateDraft.enabled?`<span class="${templateDraft.appearance==='button'?'unsubButton':'unsubLink'}">${esc(templateDraft.label)}</span>`:`<small>未启用退订；群发提交前需在本模板添加退订入口。</small>`;$('editorUnsub').innerHTML=templateDraft.enabled?`<span class="${templateDraft.appearance==='button'?'unsubButton':'unsubLink'}">${esc(templateDraft.label)}</span><button type="button" id="editUnsub">编辑</button><small>退订组件 · 按收件人生成链接</small>`:'';$('insertUnsub').textContent=templateDraft.enabled?'编辑退订入口':'＋ 添加退订入口';renderOutreachUnsubscribe();}
function renderTemplateUsage(){if(!templateStore||!outreachState)return;const plans=outreachState.plans.map(p=>'<tr><td>'+esc(p.name)+'<small>主动触达 · '+sourceTitle(p.source)+' · 计划内邮件</small></td><td>'+unsubscribeSummary(p.template)+'</td><td><button type="button" data-plan-template="'+p.id+'">'+(p.status==='COMPLETED'?'查看邮件及退订设置':'配置邮件及退订')+'</button></td></tr>').join('');const q=templateStore.quick;$('templateUsage').innerHTML=plans+'<tr><td>'+esc(q.name)+'<small>消息模板库 · 新建工单引用</small></td><td>'+unsubscribeSummary(q)+'</td><td><button type="button" data-template="quick">编辑消息模板</button></td></tr>';}
function unsubscribeSummary(t){return t.enabled?'已开启 · '+(t.appearance==='button'?'按钮':'文字链接')+' · 原生退订'+(t.native?'开启':'关闭'):'未配置退订';}
function openTemplateTargets(){openModal('选择要配置的邮件模板','<p>主动触达的邮件内容和退订配置保存在各自计划中，请选择具体计划。</p><table><thead><tr><th>计划 / 模板</th><th>退订设置</th><th>操作</th></tr></thead><tbody>'+outreachState.plans.map(p=>'<tr><td>'+esc(p.name)+'<small>'+sourceTitle(p.source)+'</small></td><td>'+unsubscribeSummary(p.template)+'</td><td><button data-plan-template="'+p.id+'">配置邮件及退订</button></td></tr>').join('')+'<tr><td>消息模板库<small>新建工单引用，独立保存</small></td><td>'+unsubscribeSummary(templateStore.quick)+'</td><td><button data-template="quick">编辑消息模板</button></td></tr></tbody></table>');}
function renderOutreachUnsubscribe(){const host=$('outreachUnsubscribeSettings'),d=outreachState?.draft;if(!host||!d||activeTemplate!=='outreach')return;const language=d.source==='TICKET_RULE'?$('outreachLanguage').selectedOptions[0].textContent:'邮件正文';host.innerHTML='<div class="outreachUnsubscribeHeading"><div><b>邮件退订设置</b><small>当前计划：'+esc(d.name||'新建定向触达')+' · '+esc(language)+'</small></div><button type="button" id="configurePlanUnsubscribe" '+(d.status==='COMPLETED'?'disabled':'')+'>'+(templateDraft.enabled?'修改退订设置':'配置退订设置')+'</button></div><p><span class="pill '+(templateDraft.enabled?'good':'')+'">'+unsubscribeSummary(templateDraft)+'</span>'+(templateDraft.enabled?'　文案：'+esc(templateDraft.label):'')+'</p><small>随第 4 步保存到当前计划，用于本计划的邮件预览和发送。</small>';}

function editUnsub(){readTemplate();const plan=activeTemplate==='outreach'?outreachState.draft:null;openModal('邮件退订设置',`<p>所属模板：<b>${esc(plan?plan.name||'新建定向触达':templateDraft.name)}</b>${plan&&plan.source==='TICKET_RULE'?' · '+esc($('outreachLanguage').selectedOptions[0].textContent):''}</p><form id="componentForm"><label class="nativeBinding"><input id="componentEnabled" type="checkbox" checked> 为当前邮件启用退订</label><div class="field"><label for="componentType">展示方式</label><select id="componentType"><option value="link">文字链接</option><option value="button">按钮</option></select></div><div class="field"><label for="componentLabel">显示文案</label><input id="componentLabel" maxlength="50" required value="${esc(templateDraft.enabled?templateDraft.label:settings.footer)}"></div><label class="nativeBinding"><input id="componentNative" type="checkbox" ${templateDraft.native!==false?'checked':''}> 同时支持邮箱原生退订</label><small>发送时使用同一退订服务生成标准邮件头；顶部是否展示取决于收件邮箱。</small><p>此设置仅保存到上方这份邮件模板。启用后在正文插入一个入口，原生退订与正文使用同一处理服务。收件人退订后，后续主动触达及新建工单批量外发会跳过该邮箱；正常工单回复不受影响。这是本次新增规则，来源模板用于追溯，换模板不能绕过。</p><div class="actions"><button class="primary" type="submit">应用到当前邮件</button><button type="button" data-close>取消</button></div></form>`);$('componentType').value=templateDraft.appearance;$('componentForm').addEventListener('submit',e=>{e.preventDefault();const label=$('componentLabel').value.trim();if(!label)return;templateDraft={...templateDraft,enabled:$('componentEnabled').checked,native:$('componentNative').checked,label,appearance:$('componentType').value};if(plan)readOutreachFields();$('modal').close();renderTemplatePreview();if(plan)renderOutreachEditor();toast(plan?'已应用到当前邮件，请在第4步保存计划':'已应用，请保存当前消息模板');});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-template-picker')){openTemplateTargets();return;}if(b.dataset.planTemplate){$('modal').close();openOutreachEditor(b.dataset.planTemplate,3);return;}if(b.dataset.template){if(b.dataset.template==='outreach'){openTemplateTargets();return;}if($('modal').open)$('modal').close();activeTemplate=b.dataset.template;templateDraft={...templateStore[activeTemplate]};renderTemplate();renderMail();show('template');return;}if(['insertUnsub','editUnsub','configurePlanUnsubscribe'].includes(b.id)){editUnsub();return;}if(b.id==='previewDraft'){readTemplate();renderTemplatePreview();mailing.previewChecked=!!templateDraft.enabled;renderGuide();showOutreachMailPreview();}if(b.id==='insertVariables'){readTemplate();openModal('插入变量',`<div class="variableList"><button data-variable="{{customer_name}}">客户姓名</button><button data-variable="{{ticket_number}}">工单编号</button><button data-variable="{{satisfaction_url}}">满意度链接</button></div><small>参考现有变量工具；退订组件使用独立的「添加退订入口」。</small>`);}if(b.dataset.variable){const box=$('templateBody'),start=box.selectionStart,end=box.selectionEnd;templateDraft.body=box.value.slice(0,start)+b.dataset.variable+box.value.slice(end);$('modal').close();renderTemplate();}});
$('templateSource').addEventListener('change',()=>{if($('templateSource').value==='outreach'){openTemplateTargets();$('templateSource').value=activeTemplate;return;}activeTemplate=$('templateSource').value;templateDraft={...templateStore[activeTemplate]};renderTemplate();renderMail();show('template');});
['templateSubject','templateBody'].forEach(id=>$(id).addEventListener('input',()=>{readTemplate();renderTemplatePreview();}));
$('templateForm').addEventListener('submit',e=>{e.preventDefault();readTemplate();if(!(activeTemplate==='quick'?templateDraft.name:templateDraft.subject).trim()||!templateDraft.body.trim()){toast('请填写名称或主题，以及正文');return;}templateStore[activeTemplate]={...templateDraft};renderMail();renderTemplatePreview();if(mailing){mailing.templateSaved=true;mailing.previewChecked=false;renderCompose();renderGuide();}toast('邮件模板与退订入口已保存');});
$('nativeVisible').addEventListener('change',()=>{$('native').hidden=!$('nativeVisible').checked;});




// 以下均为本地评审交互；模板配置是新增建议，不发送真实邮件。
const walkthroughSteps=[
{title:'选择本次群发与模板',role:'运营 / 客服',view:'compose',action:'选择主动触达或新建工单导入，按现有方式选发件邮箱，保存群发配置。此处不绑定退订。',write:'保存发送入口与本次引用的模板；不新增品牌或用途分类。'},
{title:'模板添加退订入口',role:'运营 / 客服',view:'template',action:'点「添加退订入口」，选择链接或按钮并确认，然后「保存模板」。原生退订也在此模板配置。',write:'保存当前模板的退订组件、文案及原生退订开关。'},
{title:'预览并核对邮件',role:'运营 / 客服',view:'template',action:'点工具栏的「预览」，核对右侧正文只出现一个退订入口。',write:'只更新预览；收件人专属链接在发送时生成。'},
{title:'检查并模拟群发',role:'系统',view:'compose',action:'点「检查并模拟群发」。Alex、buyer 通过；mia 人工暂停半年；bounced 永久退信。',write:'先逐人查名单，再根据所用模板生成链接与邮件头。'},
{title:'客户收到并退订',role:'收件人 Alex',view:'email',action:'正文入口 → 确认退订；或勾选模拟邮箱顶部退订，再点取消订阅。',write:'保存收件邮箱的退订记录，记录来源模板、任务入口和时间。'},
{title:'后台核对来源记录',role:'管理员',view:'list',action:'点击 Alex 的「详情」，核对来源模板、邮件、入口和持续有效状态。',write:'只读查询记录；来源模板用于追溯，不是只禁止这一份模板。'},
{title:'再次群发验证跳过',role:'系统',view:'compose',action:'再点「检查并模拟群发」。也可换发件邮箱或群发入口；另一个入口需先配置它自己的模板。',write:'已退订的 Alex 被跳过；换邮箱或模板不会清除记录。'},
{title:'普通工单回复对照',role:'系统',view:'compose',action:'点击「检查 Alex 的普通工单回复」。',write:'群发退订不拦普通工单回复；仍需原权限、渠道及硬禁发校验。'}];
function templateForEntry(){return mailing.entry==='campaign'?'outreach':'quick';}
function bindingReady(){return !!(mailing.serviceSaved&&templateStore[templateForEntry()].enabled);}
function enterMailingTemplate(){if(mailing.entry==='campaign'){openOutreachEditor(outreachState.currentId,3);return;}activeTemplate='quick';templateDraft={...templateStore.quick};renderTemplate();renderMail();show('template');}
function stepComplete(i){return [mailing.routeSaved,mailing.templateSaved&&templateStore[templateForEntry()].enabled,mailing.previewChecked,mailing.firstBatch,selfActive(),mailing.recordReviewed,!!mailing.lastBatch?.rows.some(r=>r.email===demoMail&&r.kind==='opt'),mailing.serviceChecked][i];}
function renderFlowMap(){if(!$('flowmap'))return;$('flowmap').innerHTML=walkthroughSteps.map((s,i)=>`<button class="flowNode ${stepComplete(i)||mailing.completed.includes(i)?'complete':''}" data-walkstep="${i}"><span>${String(i+1).padStart(2,'0')}　${s.role}</span><b>${s.title}</b><small>${s.write}</small><em>${stepComplete(i)||mailing.completed.includes(i)?'已完成 · 可重看':'点击操作 →'}</em></button>`).join('');}
function renderGuide(){if(!mailing)return;if(mailing.walking&&stepComplete(mailing.step)&&!mailing.completed.includes(mailing.step))mailing.completed.push(mailing.step);document.body.classList.toggle('walking',mailing.walking);$('walkbar').hidden=!mailing.walking;renderFlowMap();if(!mailing.walking)return;const s=walkthroughSteps[mailing.step];$('walkbar').innerHTML=`<div><b>操作演示 ${mailing.step+1}/8 · ${s.title}</b><small>${s.action}</small><small class="writeHint">本步数据：${s.write}</small></div><nav><button data-walk="map">完整图</button><button data-walk="prev" ${mailing.step===0?'disabled':''}>上一步</button><button class="primary" data-walk="next" ${!stepComplete(mailing.step)?'disabled':''}>${mailing.step===7?'完成演示':'下一步 →'}</button><button data-walk="exit">退出引导</button></nav>`;}
function goWalkStep(i){mailing.walking=true;mailing.step=Math.max(0,Math.min(7,i));if([1,2].includes(mailing.step))enterMailingTemplate();else{if(mailing.step===5){$('search').value=demoMail;$('filter').value='all';$('status').value='all';}show(walkthroughSteps[mailing.step].view);}renderGuide();}
function renderBindingSettings(){if(!mailing)return;$('unsubscribeServiceUrl').value=mailing.serviceUrl;$('serviceState').textContent='已预置 · 本地演示地址';$('serviceState').className='pill';}
function renderCompose(){if(!mailing)return;renderOutreachPlans();$('mailingEntry').value=mailing.entry;$('mailingSender').value=mailing.sender;const t=templateStore[templateForEntry()];$('mailingEntryHint').textContent=mailing.entry==='campaign'?'保留现有主动触达计划及计划内模板。':'保留现有新建工单批量任务及消息模板引用。';$('composeBinding').innerHTML=`<b>本次所用模板的退订设置</b><p>${esc(t.name)}</p><span class="pill ${t.enabled?'good':'wait'}">${t.enabled?'已启用退订':'未启用，群发提交前需补齐'}</span><small>发件邮箱只用于发送，不绑定退订。来源模板用于追溯，后续群发均查退订名单。</small>`; $('composeTemplate').innerHTML=`<p><b>${esc(t.name)}</b><small>${templateForEntry()==='outreach'?'主动触达计划内模板':'消息模板库引用'}</small></p><p>${esc(t.body)}</p><span class="pill">${t.enabled?'已配置'+(t.appearance==='button'?'按钮':'链接')+'：'+esc(t.label):'请编辑模板添加退订入口'}</span>${t.enabled?'<small>原生退订：'+(t.native?'已启用 · 发送时附加邮件头':'未启用')+'</small>':''}`;if(location.hash==='#compose'){document.querySelector('.top b').textContent=mailing.entry==='campaign'?'主动触达':'工单';}}
function readMailingRoute(){const entry=$('mailingEntry').value,sender=$('mailingSender').value;if(entry!==mailing.entry){mailing.templateSaved=false;mailing.previewChecked=false;}if(entry!==mailing.entry||sender!==mailing.sender)mailing.routeSaved=false;mailing.entry=entry;mailing.sender=sender;renderCompose();renderGuide();}
function batchVerdict(email,mode='bulk'){const hits=records.filter(r=>r.email===email&&statusAt(r,today)==='active');if(hits.some(r=>r.type==='hard'))return {email,kind:'hard',text:'拦截 · 永久退信'};if(mode==='bulk'&&hits.some(r=>r.type!=='hard'))return {email,kind:'opt',text:'跳过 · '+hits.filter(r=>r.type!=='hard').map(r=>sources[r.type]).join('、')};if(mode==='bulk'&&!bindingReady())return {email,kind:'unbound',text:'暂缓 · 请在本次模板添加退订入口'};return {email,kind:'pass',text:mode==='reply'?'通过群发退订检查 · 继续原发信校验':'通过 · 模拟发送'};}
function runMailing(){if(!mailing.routeSaved){toast('请先保存本次群发配置。');return;}const rows=[demoMail,'buyer@example.test','mia@example.test','bounced@example.test'].map(email=>batchVerdict(email)),t=templateStore[templateForEntry()];mailing.lastBatch={entry:mailing.entry,sender:mailing.sender,rows};if(rows.some(r=>r.email===demoMail&&r.kind==='pass')){mailing.receipt={sender:mailing.sender,entry:mailing.entry,templateName:t.name,subject:t.subject,body:t.body,label:t.label,appearance:t.appearance,url:mailing.serviceUrl+'?t=demo-alex',native:t.native};mailing.firstBatch=true;}const pass=rows.filter(r=>r.kind==='pass').length;$('batchResult').innerHTML=`<h2>模拟批次结果</h2><p>${esc(mailing.sender)} · ${esc(t.name)} · 可发送 ${pass} 人</p><table><thead><tr><th>收件人</th><th>检查结果</th></tr></thead><tbody>${rows.map(r=>'<tr><td>'+r.email+'</td><td>'+r.text+'</td></tr>').join('')}</tbody></table>${mailing.receipt?'<button type="button" data-tab="email">查看 Alex 上次收到的邮件</button>':''}<small>本地规则模拟，未发送邮件。</small>`;renderMail();renderGuide();}
function renderBoundMail(){if(!mailing)return;const r=mailing.receipt,t=templateStore[templateForEntry()],native=r?r.native:t.native,ready=!!r;$('mailSender').textContent=r?.sender||mailing.sender;$('footLink').disabled=!ready;$('nativeVisible').disabled=!ready||!native;if($('nativeVisible').disabled)$('nativeVisible').checked=false;$('native').hidden=!$('nativeVisible').checked;$('native').disabled=!ready;if(r){$('sentSubject').textContent=r.subject;$('sentBody').textContent=r.body;$('footLink').textContent=r.label;$('footLink').className=r.appearance==='button'?'unsubButton':'text';}$('fallbackHint').textContent=ready?'':'请先模拟发送；模板编辑页可预览退订组件。';$('receiptAssociation').innerHTML=`<p>来源模板：${esc(r?.templateName||t.name)}</p><p>来源入口：${r?(r.entry==='campaign'?'主动触达':'新建工单导入'):'尚未发送'}</p><p>发件邮箱：${esc(r?.sender||mailing.sender)}（仅为来源记录）</p><p>专属链接：<code>${esc(r?.url||mailing.serviceUrl+'?t=收件人专属凭证')}</code></p><p>按模板配置生成入口；退订记录用于后续群发检查。</p>${ready&&native?'<pre>List-Unsubscribe: &lt;'+esc(r.url)+'&gt;\nList-Unsubscribe-Post: List-Unsubscribe=One-Click</pre>':''}`;}
$('unsubscribeServiceForm').addEventListener('submit',e=>{e.preventDefault();let u;try{u=new URL($('unsubscribeServiceUrl').value.trim());}catch{toast('请填写 HTTPS 地址');return;}if(u.protocol!=='https:'||u.username||u.password||u.hash||u.search){toast('使用 HTTPS 服务地址，不含账号、查询参数或锚点。');return;}mailing.serviceUrl=u.href;renderBindingSettings();renderMail();toast('本地示例地址已更新，未验证真实服务');});
$('mailingForm').addEventListener('submit',e=>{e.preventDefault();readMailingRoute();mailing.routeSaved=true;activeTemplate=templateForEntry();templateDraft={...templateStore[activeTemplate]};renderTemplate();renderMail();renderCompose();renderGuide();toast('本次群发草稿已保存；发送前核对模板退订设置');});
['mailingEntry','mailingSender'].forEach(id=>$(id).addEventListener('change',readMailingRoute));
$('nativeVisible').addEventListener('change',renderBoundMail);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.walkstep!==undefined){goWalkStep(Number(b.dataset.walkstep));return;}if(b.dataset.walk){switch(b.dataset.walk){case 'map':show('flow');break;case 'prev':goWalkStep(mailing.step-1);break;case 'next':if(!stepComplete(mailing.step))return;if(mailing.step===7){mailing.walking=false;renderGuide();show('flow');toast('完整演示已完成');}else goWalkStep(mailing.step+1);break;case 'exit':mailing.walking=false;renderGuide();break;}return;}switch(b.id){case 'startWalk':reset(true);goWalkStep(0);break;case 'editMailingTemplate':enterMailingTemplate();break;case 'runMailing':runMailing();break;case 'checkService':{const v=batchVerdict(demoMail,'reply');mailing.serviceChecked=v.kind==='pass';$('serviceResult').innerHTML='<h3>普通工单回复 · Alex</h3><span class="pill">'+v.text+'</span><p>退订记录继续有效；本次只检查普通回复不被群发退订拦截。</p>';renderGuide();break;}case 'walkManual':show('unsubscribes');contactNavigate('unsubscribes',true);break;}});


// 按测试环境现有主动触达页面复刻；以下状态全部本地演示。
function resetOutreach(){const mk=(id,name,source,status,group='未分组')=>({id,name,source,status,group,schedule:'once',replyWindow:168,window:168,max:1,cooldown:0,scope:'本计划·同一客户',hitAction:'跳过本次投递',sender:'hello@example.test',template:newTemplate(name),uploaded:source==='EXCEL_IMPORT',conditions:[{field:'工单状态',op:'是',value:'待处理'},{field:'AI 处理状态',op:'是',value:'AI 处理中'},{field:'最后客户来信时间',op:'超过（小时）',value:'24'}],or:[],translate:false});outreachState={plans:[mk('demo-1','产品调研邀请','EXCEL_IMPORT','DRAFT'),mk('demo-2','客户跟进邮件','TICKET_RULE','DRAFT','客户关怀'),mk('demo-3','历史关怀计划','TICKET_RULE','PAUSED','客户关怀')],currentId:'demo-1',draft:null,step:1,filter:'',runs:[],nextId:4};}
function sourceTitle(source){return source==='TICKET_RULE'?'工单条件':'Excel 名单';}
function statusTitle(status){return ({DRAFT:'待启用',ACTIVE:'运行中',PAUSED:'已暂停',COMPLETED:'已完成'})[status];}
function syncOutreachView(tab){const isOutreach=['compose','outreachEditor'].includes(tab);document.body.classList.toggle('outreachpage',isOutreach);document.body.classList.toggle('outreacheditor',tab==='outreachEditor');if(isOutreach){document.querySelector('.top b').textContent='主动触达';document.querySelectorAll('.appnav>span').forEach((n,i)=>n.classList.toggle('selected',i===3));}if(tab==='compose')renderOutreachPlans();if(tab==='outreachEditor'){if(!outreachState.draft)openOutreachEditor(outreachState.currentId,3);else {mountOutreachTemplate();renderOutreachEditor();}}}
function renderOutreachPlans(){if(!outreachState||!$('outreachPlans'))return;const all=outreachState.plans,scheduleFilter=$('outreachScheduleFilter').value,q=$('outreachSearch').value.trim().toLowerCase(),source=$('outreachSourceFilter').value,group=$('outreachGroupFilter').value;let items=all.filter(p=>(!outreachState.filter||p.status===outreachState.filter)&&(!source||p.source===source)&&(!scheduleFilter||p.schedule===scheduleFilter)&&(!group||p.group===group)&&(!q||(p.name+' '+p.id).toLowerCase().includes(q)));if($('outreachSort').value==='name')items.sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'));$('outreachStatusTabs').innerHTML=[['','全部'],['ACTIVE','运行中'],['DRAFT','待启用'],['PAUSED','已暂停'],['COMPLETED','已完成']].map(([v,label])=>'<button role="tab" data-outreach-status="'+v+'" aria-selected="'+(outreachState.filter===v)+'">'+label+' <span>'+all.filter(p=>!v||p.status===v).length+'</span></button>').join('');$('outreachPlanCount').textContent='共 '+items.length+' 个计划';$('outreachPlans').innerHTML=items.length?items.map(p=>'<tr><td><strong>'+esc(p.name)+'</strong><small>v1 · '+(p.schedule==='once'?'单次执行':'周期执行')+'</small></td><td>'+sourceTitle(p.source)+'</td><td>邮件</td><td>'+esc(p.group)+'</td><td><span class="pill">'+statusTitle(p.status)+'</span></td><td>'+(p.status==='COMPLETED'?'已执行':'启动后执行')+'</td><td><div class="outreachRowActions"><button data-start-plan="'+p.id+'" '+(p.status==='COMPLETED'?'disabled':'')+'>'+(p.status==='ACTIVE'?'暂停计划':'启动计划')+'</button><button data-test-plan="'+p.id+'" '+(p.source!=='TICKET_RULE'?'disabled':'')+'>匹配测试</button><button data-plan-runs="'+p.id+'">执行记录</button><button data-plan-more="'+p.id+'">更多 ▾</button></div></td></tr>').join(''):'<tr><td colspan="7" class="empty">没有匹配的计划</td></tr>';}
function openOutreachEditor(id,step=1){const saved=outreachState.plans.find(p=>p.id===id);if(saved){outreachState.currentId=id;outreachState.draft=JSON.parse(JSON.stringify(saved));}else {const base=JSON.parse(JSON.stringify(outreachState.plans[0]));outreachState.currentId=null;outreachState.draft={...base,id:null,name:'',source:'TICKET_RULE',status:'DRAFT',group:'未分组',uploaded:false,sender:'',template:{...newTemplate('新建定向触达'),subject:'',body:''}};}outreachState.step=step;outreachState.language='AUTO';$('outreachLanguage').value='AUTO';activeTemplate='outreach';templateStore.outreach={...outreachState.draft.template};templateDraft={...outreachState.draft.template};mailing.entry='campaign';mailing.routeSaved=!!saved;mailing.sender=outreachState.draft.sender;renderTemplate();fillOutreachFields();show('outreachEditor');renderOutreachEditor();renderGuide();$('outreachEditor').querySelector('.outreachEditorScroll').scrollTop=0;}
function fillOutreachFields(){const d=outreachState.draft;const fields={outreachGroup:d.group,outreachName:d.name,outreachAfterAction:d.afterAction||'',outreachActionValue:d.actionValue||'',outreachAudience:d.source,outreachSubject:d.template.subject,outreachSender:d.sender,outreachSchedule:d.schedule,outreachReplyWindow:d.replyWindow,outreachWindow:d.window,outreachMaxSuccess:d.max,outreachCooldown:d.cooldown,outreachFrequencyScope:d.scope,outreachHitAction:d.hitAction};for(const [id,value]of Object.entries(fields))$(id).value=value;$('outreachTranslate').checked=d.translate;renderOutreachConditions();}
function readOutreachFields(){const d=outreachState.draft;if(!d)return;d.name=(outreachState.step===4&&$('outreachConfirmName')?$('outreachConfirmName'):$('outreachName')).value.trim();d.afterAction=$('outreachAfterAction').value;d.actionValue=$('outreachActionValue').value;d.group=$('outreachGroup').value;d.source=$('outreachAudience').value;d.schedule=$('outreachSchedule').value;d.replyWindow=Number($('outreachReplyWindow').value);d.window=Number($('outreachWindow').value);d.max=Number($('outreachMaxSuccess').value);d.cooldown=Number($('outreachCooldown').value);d.scope=$('outreachFrequencyScope').value;d.hitAction=$('outreachHitAction').value;d.sender=d.source==='EXCEL_IMPORT'?$('outreachSender').value:'hello@example.test';d.translate=$('outreachTranslate').checked;readTemplate();if(d.source==='EXCEL_IMPORT')templateDraft.subject=$('outreachSubject').value;else templateDraft.subject='Re: 关于你的产品使用反馈';if(outreachState.language&&outreachState.language!=='AUTO'){d.languageTemplates=d.languageTemplates||{};d.languageTemplates[outreachState.language]={...templateDraft};}else d.template={...templateDraft};mailing.sender=d.sender;}
function mountOutreachTemplate(){if(!$('sharedTemplateEditor'))return;const isPlan=activeTemplate==='outreach';const host=isPlan?$('outreachContentHost'):$('quickTemplateHost');if($('sharedTemplateEditor').parentElement!==host)host.appendChild($('sharedTemplateEditor'));$('previewDraft').textContent=isPlan?'预览邮件':'预览';if(isPlan){$('templateSource').closest('.field').hidden=true;$('templateSubject').closest('.field').hidden=true;document.querySelector('#sharedTemplateEditor .languageRow').hidden=true;$('templateBody').closest('.field').querySelector('label').textContent=outreachState?.draft?.source==='TICKET_RULE'?$('outreachLanguage').selectedOptions[0].textContent:'邮件正文';$('templateSubject').required=false;}else{$('sharedTemplateEditor').querySelectorAll('input,select,textarea,button').forEach(n=>n.disabled=false);$('templateSource').closest('.field').hidden=false;$('templateSubject').closest('.field').hidden=false;document.querySelector('#sharedTemplateEditor .languageRow').hidden=false;$('templateBody').closest('.field').querySelector('label').textContent='正文';$('templateSubject').required=true;}}
function renderOutreachEditor(){const d=outreachState.draft;if(!d)return;$('outreachName').value=d.name||'';const step=outreachState.step,ticket=d.source==='TICKET_RULE',readOnly=d.status==='COMPLETED',preview=$('outreachTicketNumber')?.closest('.outreachOriginalPreview');$('outreachEditorTitle').textContent=d.id?(readOnly?'查看设置 · ':'修改设置 · ')+(d.name||'定向触达'):'新建定向触达';$('outreachStepper').innerHTML=['选择触达客户','设置发送计划','编写邮件内容','确认并保存'].map((t,i)=>'<button type="button" data-outreach-step="'+(i+1)+'" aria-current="'+(step===i+1?'step':'false')+'"><span>'+(i+1)+'</span>'+t+'</button>').join('<i></i>');document.querySelectorAll('[data-outreach-panel]').forEach(n=>n.hidden=Number(n.dataset.outreachPanel)!==step);$('outreachTicketAudience').hidden=!ticket;$('outreachExcelAudience').hidden=ticket;$('outreachSenderSection').hidden=ticket;$('outreachLanguageSettings').hidden=!ticket;$('outreachChannelSection').hidden=ticket;$('outreachIntervalField').hidden=d.schedule!=='recurring';$('outreachFileState').textContent=d.uploaded?'演示名单.xlsx：4 行可触达，0 行需修正':'尚未选择文件';$('outreachPrev').hidden=step===1;$('outreachNext').textContent=step===4?(readOnly?'返回列表':d.id?'保存计划':'创建计划'):'下一步';$('outreachEditor').querySelectorAll('input,select,textarea').forEach(n=>n.disabled=readOnly);$('insertUnsub').disabled=readOnly;$('editUnsub')&&($('editUnsub').disabled=readOnly);mountOutreachTemplate();renderOutreachUnsubscribe();const form=$('templateForm');let hint=$('outreachOriginalSubjectHint');if(!hint){hint=document.createElement('p');hint.id='outreachOriginalSubjectHint';hint.className='outreachSubjectHint';form.insertBefore(hint,$('templateBody').closest('.field'));}hint.hidden=!ticket;hint.textContent='邮件主题将自动使用原邮件主题（Re:），无需填写。';$('outreachContentValidation').innerHTML=d.template.body.trim().length<20?'<div class="outreachContentWarning"><b>邮件内容需要修改，暂不能正式启动</b><p>自定义正文至少 20 个有效文字字符；正式发送前还会检查实际邮件。</p><small>可以保存当前配置；修改问题后才能正式发送。</small></div>':'';$('outreachConfirmation').innerHTML='<dl><dt><label for="outreachConfirmName">计划名称</label></dt><dd><input id="outreachConfirmName" aria-label="计划名称（第四步）" placeholder="请输入计划名称" value="'+esc(d.name||'')+'" required '+(readOnly?'disabled':'')+'></dd><dt>触达对象</dt><dd>'+sourceTitle(d.source)+'</dd><dt>发送渠道</dt><dd>邮件</dd><dt>翻译兜底</dt><dd>'+(d.translate?'已开启':'未开启')+'</dd><dt>业务分组</dt><dd>'+esc(d.group)+'</dd><dt>执行方式</dt><dd>'+(d.schedule==='once'?'单次执行':'周期执行')+'</dd><dt>限制范围</dt><dd>'+esc(d.scope)+'</dd><dt>成功发送上限</dt><dd>每 '+d.window+' 小时内最多成功发送 '+d.max+' 次</dd><dt>两次成功间隔（分钟）</dt><dd>'+(d.cooldown?d.cooldown+' 分钟':'不额外限制')+'</dd><dt>命中限制后处理</dt><dd>'+esc(d.hitAction)+'</dd><dt>客户回复观察窗口</dt><dd>'+d.replyWindow+' 小时（不会到期自动补发）</dd></dl><div class="outreachUnsubSummary"><b>邮件退订 <button class="mark" data-note="6">07</button></b><p>'+(templateDraft.enabled?'已添加'+(templateDraft.appearance==='button'?'按钮':'文字链接')+'：'+esc(templateDraft.label)+'；原生退订'+(templateDraft.native?'已启用':'未启用'):'未添加退订入口；正式启动前需回第三步补齐。')+'</p><small>客户确认退订后写入名单，后续群发检查；普通工单回复不受影响。</small></div>'+outreachConfirmationDetails(d);$('outreachEditor').querySelector('.outreachSaveHint').innerHTML='<h3>保存前请确认</h3><ul>'+(ticket?'<li>工单条件触达：仅筛选最近 30 天更新、且最后一次客户来信在 30 天内的工单。</li><li>发信可能重新打开已解决工单。“设为已解决”在发信状态变化后执行，不会恢复原解决时间及全部统计。</li>':'')+'<li>保存不会启动发送，正式启动时会再次确认影响。</li>'+(ticket?'<li>推荐保存后从列表发起测试，但不强制。测试结束或终止后，再正式启动。</li>':'')+'</ul>';if(preview)(step===4&&ticket?$('outreachConfirmPreview'):$('outreachTicketAudience')).appendChild(preview);}

function outreachConfirmationDetails(d){
 const ticket=d.source==='TICKET_RULE',conditions=(title,rows)=>rows?.length?'<p><b>'+title+'</b></p><ul>'+rows.map(c=>'<li>'+esc(c.field)+' · '+esc(c.op)+' · '+esc(c.value)+'</li>').join('')+'</ul>':'';
 return (ticket?'<section class="outreachFormSection"><h3>哪些工单会命中</h3>'+conditions('满足全部条件（AND）',d.conditions)+conditions('满足任一条件（OR，可选）',d.or)+(!d.conditions?.length&&!d.or?.length?'<p>未配置匹配条件。</p>':'')+'</section>':'')+'<section class="outreachFormSection"><h3>发送前邮箱检查</h3><p>'+(ticket?'工单满足以上条件后，还须检查对应客户邮箱。':'名单中的每个收件邮箱在发送前均须检查。')+'</p><ul><li>邮箱未命中当前有效的邮件退订记录，包括客户自行退订和员工代为退订。</li><li>邮箱未进入黑名单；同时继续检查已有地址抑制、重复发送限制等发送条件。</li><li>退订、黑名单检查始终生效，不因更换计划、模板或发件邮箱而绕过。</li></ul><p>命中退订或黑名单的邮箱将被排除，并在执行记录中保留原因。匹配预览不代表最终可发送，实际发送前仍须重新检查。</p></section>'+(ticket?'<section class="outreachFormSection"><h3>发信后会发生什么</h3><p><b>发信的默认影响</b></p><ul class="outreachActionHelp"><li>在命中的原工单新增 1 条去信。</li><li>人工身份发信后，工单变为“处理中”。</li><li>AI 身份发信后，工单变为“AI 处理中”。</li><li>未配置指派动作时，保留原负责人；未分配仍保持未分配。</li></ul><p><b>发送成功后，按以下顺序执行</b></p>'+(d.afterAction?'<ul><li>'+esc(d.afterAction)+' · '+esc(d.actionValue||'未填写')+'</li></ul>':'<p>未配置后续动作。</p>')+'<p>未配置状态动作：发信后将保持“处理中”或“AI 处理中”。</p></section><div id="outreachConfirmPreview"></div>':'');
}
document.addEventListener('input',e=>{if(!['outreachName','outreachConfirmName'].includes(e.target.id)||!outreachState?.draft||outreachState.draft.status==='COMPLETED')return;const value=e.target.value;outreachState.draft.name=value;for(const id of ['outreachName','outreachConfirmName'])if($(id)&&$(id)!==e.target)$(id).value=value;});

function renderOutreachConditions(){for(const key of ['conditions','or']){const host=$(key==='conditions'?'outreachAndConditions':'outreachOrConditions');host.innerHTML=outreachState.draft[key].map((c,i)=>'<div class="outreachConditionRow"><select data-condition-key="'+key+'" data-condition-index="'+i+'" data-condition-part="field" aria-label="条件字段"><option>'+esc(c.field)+'</option><option>工单状态</option><option>AI 处理状态</option><option>最后客户来信时间</option></select><select data-condition-key="'+key+'" data-condition-index="'+i+'" data-condition-part="op" aria-label="匹配关系"><option>'+esc(c.op)+'</option><option>是</option><option>不是</option><option>超过（小时）</option></select><input aria-label="条件值" data-condition-key="'+key+'" data-condition-index="'+i+'" data-condition-part="value" value="'+esc(c.value)+'"><button class="text" data-remove-condition="'+key+':'+i+'">移除</button></div>').join('<small class="outreachAnd">'+(key==='conditions'?'AND':'OR')+'</small>');}}
function advanceOutreach(){readOutreachFields();const d=outreachState.draft,step=outreachState.step;if(step===1){if(d.source==='EXCEL_IMPORT'&&!d.uploaded){toast('请选择名单文件；演示可使用示例文件');return;}mailing.routeSaved=true;}if(step===2){if(d.source==='EXCEL_IMPORT'&&(!d.sender||!d.template.subject.trim())){toast('请填写邮件主题并选择发件邮箱');return;}if(d.replyWindow<1||d.window<1||d.max<1){toast('请检查发送计划的数值');return;}}if(step===4){if(d.status==='COMPLETED'){show('compose');return;}saveOutreachPlan();return;}outreachState.step++;renderOutreachEditor();$('outreachEditor').querySelector('.outreachEditorScroll').scrollTop=0;renderGuide();}
function saveOutreachPlan(){readOutreachFields();const d=outreachState.draft;d.template.name=d.name;if(!d.name){toast('请填写计划名称');$('outreachConfirmName')?.focus();return;}if(!d.template.body.trim()){toast('请填写邮件正文');return;}if(!d.id){d.id='demo-'+outreachState.nextId++;outreachState.plans.unshift(JSON.parse(JSON.stringify(d)));}else {const i=outreachState.plans.findIndex(p=>p.id===d.id);outreachState.plans[i]=JSON.parse(JSON.stringify(d));}outreachState.currentId=d.id;templateStore.outreach={...d.template};mailing.routeSaved=true;mailing.templateSaved=true;renderMail();renderGuide();renderTemplateUsage();persistPrototype();show('compose');toast('计划和邮件退订设置已保存；没有启动发送（本地演示）');}
function showOutreachMailPreview(){if(activeTemplate!=='outreach'){toast('右侧预览已更新');return;}readOutreachFields();const d=outreachState.draft,previewTemplate={...templateDraft};openModal('预览邮件','<p class="prototypeNotice">本地演示：不查询真实工单，不发送邮件。</p>'+(d.source==='TICKET_RULE'?'<div class="field"><label for="previewTicketNumber">工单号</label><input id="previewTicketNumber" placeholder="填写示例工单号"><small>正式系统沿用已有按工单预览；下方使用合成示例。</small></div>':'')+'<article class="outreachMailPreview"><h3>'+esc(previewTemplate.subject)+'</h3><p>'+esc(previewTemplate.body)+'</p>'+(previewTemplate.enabled?'<span class="'+(previewTemplate.appearance==='button'?'unsubButton':'unsubLink')+'">'+esc(previewTemplate.label)+'</span>':'<small>尚未添加退订入口</small>')+'</article><p>原生退订：'+(previewTemplate.enabled&&previewTemplate.native?'发送时生成标准邮件头，顶部展示由收件邮箱决定':'未启用')+'</p><div class="actions"><button data-close>关闭预览</button></div>');}
function confirmOutreachStart(id){const p=outreachState.plans.find(x=>x.id===id);if(p.status==='COMPLETED'){toast('已完成的计划不能直接重新启动，可复制后创建新计划。');return;}if(p.status==='ACTIVE'){p.status='PAUSED';renderOutreachPlans();return;}if(!p.template.enabled||p.template.body.trim().length<20){openModal('正式启动前请补齐邮件内容','<p>'+(!p.template.enabled?'此计划的邮件模板尚未添加退订入口，请回第三步添加并保存。':'请填写完整邮件正文。')+'</p><div class="actions"><button class="primary" data-plan-edit="'+id+'" data-edit-step="3">修改邮件内容</button><button data-close>取消</button></div>');return;}openModal('确认启动计划','<p><b>'+esc(p.name)+'</b></p><p>受众来源：'+sourceTitle(p.source)+'；发送渠道：邮件。</p><div class="outreachUnsubSummary"><b>退订检查</b><p>正式提交前逐人检查退订名单、员工代为退订及硬禁发，命中收件人会被跳过或拦截。</p></div><p class="prototypeNotice">本地演示使用 4 个合成收件人。确认后只生成模拟执行记录，不发送真实邮件、不修改测试环境。</p><div class="actions"><button class="primary" data-confirm-start="'+id+'">确认启动（本地演示）</button><button data-close>取消</button></div>');}
function startOutreachDemo(id){const p=outreachState.plans.find(x=>x.id===id);outreachState.currentId=id;mailing.entry='campaign';mailing.sender=p.sender;mailing.routeSaved=true;templateStore.outreach={...p.template};activeTemplate='outreach';templateDraft={...p.template};runMailing();outreachState.runs.unshift({id:outreachState.runs.length+1,planId:id,time:'2026-11-05 10:30:00',rows:JSON.parse(JSON.stringify(mailing.lastBatch.rows))});p.status=p.schedule==='once'?'COMPLETED':'ACTIVE';$('modal').close();renderOutreachPlans();showOutreachRuns(id);}
function showOutreachRuns(id){const p=outreachState.plans.find(x=>x.id===id),runs=outreachState.runs.filter(r=>r.planId===id);openModal(p.name+' · 执行记录',runs.length?runs.map(r=>'<div class="outreachRun"><h3>批次 #'+r.id+' · '+r.time+'</h3><p>'+r.rows.filter(x=>x.kind==='pass').length+' 已发送 / '+r.rows.filter(x=>x.kind==='opt').length+' 退订或员工代为退订排除 / '+r.rows.filter(x=>x.kind==='hard').length+' 硬禁发拦截</p><table><thead><tr><th>收件人</th><th>结果</th><th>排除/失败原因</th></tr></thead><tbody>'+r.rows.map(x=>'<tr><td>'+x.email+'</td><td>'+(x.kind==='pass'?'已发送（模拟）':'已排除')+'</td><td>'+esc(x.text)+'</td></tr>').join('')+'</tbody></table></div>').join('')+'<div class="prototypeTools"><small>评审工具</small><button id="viewDemoReceipt">查看 Alex 上次收到的邮件</button><button id="reviewReplyModal">普通工单回复对照</button></div>':'<p>还没有执行批次。启用后会在计划时间生成第一批。</p>');}
function openOutreachMore(id){openModal('计划操作','<div class="outreachMoreMenu"><button data-plan-edit="'+id+'">'+(outreachState.plans.find(p=>p.id===id).status==='COMPLETED'?'查看设置':'修改设置')+'</button><button data-copy-plan="'+id+'">复制</button><button data-plan-runs="'+id+'">执行记录</button></div>');}
function openGroupDemo(){openModal('管理分组','<p class="prototypeNotice">本地演示分组；不修改系统现有业务分组。</p><table><thead><tr><th>业务分组</th><th>计划数</th></tr></thead><tbody>'+['未分组','客户关怀'].map(g=>'<tr><td>'+g+'</td><td>'+outreachState.plans.filter(p=>p.group===g).length+'</td></tr>').join('')+'</tbody></table><div class="actions"><button id="addLocalGroup">新建分组</button><button data-close>关闭</button></div>');}
function openNewGroup(){openModal('新建分组','<form id="localGroupForm"><div class="field"><label for="localGroupName">分组名称</label><input id="localGroupName" required maxlength="40"></div><div class="actions"><button type="submit" class="primary">创建（本地演示）</button><button type="button" data-close>取消</button></div></form>');$('localGroupForm').onsubmit=e=>{e.preventDefault();const v=$('localGroupName').value.trim();if(!v)return;for(const id of ['outreachGroup','outreachGroupFilter'])if(!Array.from($(id).options).some(o=>o.value===v))$(id).add(new Option(v,v));if(outreachState.draft){$('outreachGroup').value=v;outreachState.draft.group=v;}$('modal').close();};}
notes.push(['主动触达页面复刻依据','现状核验：2026-11-05内置浏览器只读查看测试环境 /botdesk#/service-outreach 计划列表与新建四步编辑，区分工单条件和Excel名单；未保存或启动任何测试计划。GitLab最新文件跳转登录，补充参考此前已核验master文件及本地归档，不宣称最新提交或生产版本。','本期新增：仅第三步正文工具栏的退订入口、第四步摘要、启动前检查及执行记录中的退订原因；列表、业务分组和四步顺序沿用现有页面。合成数据不冒用环境里的计划。','边界：工单条件使用原工单主题与发件配置；Excel名单在第二步设置主题和发件邮箱。保存计划不会发信，原生退订与正文共用处理服务。']);
walkthroughSteps[0]={title:'打开现有主动触达计划',role:'运营 / 客服',view:'compose',action:'从计划列表点「更多 → 修改设置」或「新建定向触达」，按原有四步配置。首步完成选择客户后即可继续评审引导。',write:'沿用计划列表、业务分组、工单条件/Excel名单和四步编辑。'};
walkthroughSteps[1].action='在原第三步「编写邮件内容」点添加退订入口，再到第四步保存计划；保存不会启动发送。';
walkthroughSteps[2].action='在原第三步点击「预览邮件」，核对正文退订入口；关闭后可回列表。';
walkthroughSteps[3].action='回到计划列表，点「启动计划」，核对影响后确认本地演示；在执行记录查看逐人结果。';
walkthroughSteps[6].action='回到原计划列表，可复制已完成计划，再启动本地演示；Alex仍会因已退订而排除。';
walkthroughSteps[7].view='send';walkthroughSteps[7].action='在评审发送检查选择普通工单回复，检查Alex；群发退订不阻断普通回复。';
const baseSimulate=simulate;simulate=function(){baseSimulate();if($('channel').value==='reply'){mailing.serviceChecked=true;renderGuide();}};
const oldGoWalkStep=goWalkStep;goWalkStep=function(i){oldGoWalkStep(i);if(i===7){$('channel').value='reply';$('target').value=demoMail;}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.outreachStep){readOutreachFields();outreachState.step=Number(b.dataset.outreachStep);renderOutreachEditor();$('outreachEditor').querySelector('.outreachEditorScroll').scrollTop=0;return;}if(b.dataset.outreachStatus!==undefined){outreachState.filter=b.dataset.outreachStatus;renderOutreachPlans();return;}if(b.dataset.planMore){openOutreachMore(b.dataset.planMore);return;}if(b.dataset.planEdit){$('modal').close();openOutreachEditor(b.dataset.planEdit,Number(b.dataset.editStep)||1);return;}if(b.dataset.copyPlan){const id=b.dataset.copyPlan;$('modal').close();openOutreachEditor(id,1);outreachState.draft.id=null;outreachState.currentId=null;outreachState.draft.name+='（副本）';outreachState.draft.status='DRAFT';fillOutreachFields();renderOutreachEditor();return;}if(b.dataset.startPlan){confirmOutreachStart(b.dataset.startPlan);return;}if(b.dataset.confirmStart){startOutreachDemo(b.dataset.confirmStart);return;}if(b.dataset.planRuns){if($('modal').open)$('modal').close();showOutreachRuns(b.dataset.planRuns);return;}if(b.dataset.testPlan){const p=outreachState.plans.find(x=>x.id===b.dataset.testPlan);openModal('匹配测试 · '+p.name,'<p>本地预览使用合成工单，不查询或修改真实工单。匹配测试与正式启动分别处理。</p><div class="field"><label for="testTicketInput">工单号</label><input id="testTicketInput" placeholder="示例工单号"></div><button id="localMatchTest">预览，不发送</button><div id="localMatchTestResult"></div>');return;}if(b.dataset.addCondition){const key=b.dataset.addCondition==='and'?'conditions':'or';outreachState.draft[key].push({field:'工单状态',op:'是',value:'待处理'});renderOutreachConditions();return;}if(b.dataset.removeCondition){const[key,index]=b.dataset.removeCondition.split(':');outreachState.draft[key].splice(Number(index),1);renderOutreachConditions();return;}switch(b.id){case 'newOutreachPlan':openOutreachEditor(null,1);break;case 'outreachBack':show('compose');break;case 'outreachNext':advanceOutreach();break;case 'outreachPrev':readOutreachFields();outreachState.step=Math.max(1,outreachState.step-1);renderOutreachEditor();break;case 'manageOutreachGroups':openGroupDemo();break;case 'newOutreachGroup':case 'addLocalGroup':openNewGroup();break;case 'outreachChooseFile':openModal('选择名单文件 · 本地演示','<p>这里演示已有的Excel导入结果，不上传到测试系统。</p><p>演示名单.xlsx：Alex、buyer、mia、bounced，共4个合成地址。</p><button class="primary" id="useDemoAudience">使用演示文件</button>');break;case 'useDemoAudience':outreachState.draft.uploaded=true;$('modal').close();renderOutreachEditor();break;case 'outreachDownload':{const blob=new Blob(['Email\r\nalex@example.test\r\nbuyer@example.test\r\nmia@example.test\r\nbounced@example.test\r\n'],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='触达名单-演示.csv';a.click();URL.revokeObjectURL(a.href);toast('已下载合成示例CSV；不是线上Excel模板');break;}case 'outreachMatchPreview':if(!$('outreachTicketNumber').value.trim()){toast('请输入示例工单号');break;}$('outreachMatchResult').innerHTML='<p class="outreachInfo">演示匹配：将向原工单追加1条去信，不新建工单；发信前仍检查退订名单。</p>';break;case 'localMatchTest':$('localMatchTestResult').innerHTML='<p class="outreachInfo">合成工单符合当前演示条件；未执行真实查询或投递。</p>';break;case 'viewDemoReceipt':$('modal').close();show('email');break;case 'reviewReplyModal':$('modal').close();case 'reviewReply':show('send');$('channel').value='reply';$('target').value=demoMail;break;}});
['outreachSearch','outreachGroupFilter','outreachSourceFilter','outreachSort','outreachScheduleFilter'].forEach(id=>$(id).addEventListener(id==='outreachSearch'?'input':'change',renderOutreachPlans));
['outreachAudience','outreachSchedule'].forEach(id=>$(id).addEventListener('change',()=>{readOutreachFields();renderOutreachEditor();}));
$('outreachAfterAction').addEventListener('change',()=>{$('outreachActionValue').hidden=!$('outreachAfterAction').value;});
document.addEventListener('change',e=>{const n=e.target;if(n.dataset.conditionKey)outreachState.draft[n.dataset.conditionKey][Number(n.dataset.conditionIndex)][n.dataset.conditionPart]=n.value;});
$('templateBody').addEventListener('input',()=>{if(activeTemplate==='outreach'&&outreachState.draft)readOutreachFields();});

$('outreachLanguage').addEventListener('change',()=>{const next=$('outreachLanguage').value;readOutreachFields();outreachState.language=next;const d=outreachState.draft;templateDraft=next==='AUTO'?{...d.template}:{...(d.languageTemplates?.[next]||{...d.template,body:'',enabled:false})};renderTemplate();renderOutreachEditor();});
document.addEventListener('click',e=>{const n=e.target.closest('[data-nav-view]');if(n)show(n.dataset.navView);});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.dataset.navView){e.preventDefault();show(e.target.dataset.navView);}});
// 仅保存本地已提交的示例配置；编辑草稿不会自动覆盖计划。
function persistPrototype(){syncContactRecords();try{localStorage.setItem('unsubscribe-prototype-v6',JSON.stringify({plans:outreachState.plans,currentId:outreachState.currentId,nextId:outreachState.nextId,runs:outreachState.runs,settings,quick:templateStore.quick,records,seq,mailing}));}catch{}}
function restorePrototype(){try{const saved=JSON.parse(localStorage.getItem('unsubscribe-prototype-v6')||'null');if(!saved?.plans?.length)return;Object.assign(outreachState,{plans:saved.plans,currentId:saved.currentId,nextId:saved.nextId,runs:saved.runs||[],draft:null});settings={...defaults,...saved.settings};templateStore.quick=saved.quick||templateStore.quick;records=saved.records||records;seq=saved.seq||seq;mailing={...mailing,...saved.mailing,walking:false};$('footer').value=settings.footer;$('term').value=settings.term;renderTemplateUsage();renderList();renderGuide();}catch{}}
document.addEventListener('submit',()=>queueMicrotask(persistPrototype));
document.addEventListener('click',()=>queueMicrotask(persistPrototype));
let contactBridgeReady=false;
let contactKnownRecords=new Map();
let contactPendingRoute=null;
function contactPost(message){$('contactsFrame')?.contentWindow?.postMessage(message,location.origin);}
function contactNavigate(page,add=false){contactPendingRoute={page,add};contactPost({type:'contact-navigate',page,add});}
function syncContactsView(route){document.body.classList.toggle('contactspage',!!route);if(!route)return;document.querySelector('.top b').textContent='联系人';document.querySelectorAll('.appnav>span').forEach((n,i)=>n.classList.toggle('selected',i===1));history.replaceState(null,'','#'+route);contactNavigate(route);}
function syncContactRecords(){if(!contactBridgeReady||!records)return;const changed=records.filter(r=>['manual','self'].includes(r.type)&&contactKnownRecords.get(String(r.id))!==JSON.stringify(r));if(!changed.length)return;for(const r of changed)contactKnownRecords.set(String(r.id),JSON.stringify(r));contactPost({type:'contact-upsert',records:changed});}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('contactsFrame')?.contentWindow)return;if(e.data?.type==='contact-reviewed'){mailing.recordReviewed=true;renderGuide();return;}if(e.data?.type!=='contact-state')return;const m=e.data;if(!contactBridgeReady){const previous=records.filter(r=>['manual','self'].includes(r.type));contactBridgeReady=true;contactPost({type:'contact-init',records:previous});if(contactPendingRoute)contactPost({type:'contact-navigate',...contactPendingRoute});}contactKnownRecords=new Map((m.unsubscribes||[]).map(r=>[String(r.id),JSON.stringify(r)]));records=[...records.filter(r=>r.type==='hard'&&!r.sharedBlacklist),...(m.blacklist||[]).map(r=>({id:'shared-blacklist:'+r.email,type:'hard',email:r.email,start:r.time.slice(0,10),end:'',reason:'黑名单：'+r.reason,history:[],ended:false,sharedBlacklist:true})),...(m.unsubscribes||[])];seq=Math.max(seq,...records.map(r=>typeof r.id==='number'?r.id:0));if(document.body.classList.contains('contactspage')&&['contacts','blacklist','unsubscribes'].includes(m.page))history.replaceState(null,'','#'+m.page);renderList();renderGuide();persistPrototype();});
$('contactsFrame').addEventListener('load',()=>contactPost({type:'contact-request'}));
reset();restorePrototype();show(location.hash.slice(1)||'compose');
